import { useEffect, useState } from "react";
import "./App.css";
import { supabase } from "./Login";

function App() {
  const [users, setUsers] = useState([]);
  const [streamsStatus, setStreamsStatus] = useState({});

  const checkStreamStatus = async (nick) => {
    try {
      const response = await fetch(
        `http://fawe.online:3000/live/${nick}.m3u8`
      );
      if (response.ok) {
        return "Live";
      } else {
        return "Offline";
      }
    } catch (error) {
      console.error("Stream check error:", error);
      return "Offline";
    }
  };

  useEffect(() => {
    const fetchUsers = async () => {
      const { data } = await supabase.from("Users").select();
      setUsers(data || []);
    };

    fetchUsers();
  }, []);

  useEffect(() => {
    const fetchStreamsStatus = async () => {
      if (users.length > 0) {
        const status = {};
        for (const user of users) {
          const statusText = await checkStreamStatus(user.Nick);
          status[user.Nick] = statusText;
        }
        setStreamsStatus(status);
      }
    };

    if (users.length > 0) {
      fetchStreamsStatus();
      const interval = setInterval(() => {
        fetchStreamsStatus();
      }, 30000);

      return () => clearInterval(interval);
    }
  }, [users]);

  return (
    <div className="app-container">
      <h1>DEFLStream</h1>
      <div className="user-list">
        {users
          ?.sort((a, b) => {
            const aStatus = streamsStatus[a.Nick] === "Live" ? 1 : 0;
            const bStatus = streamsStatus[b.Nick] === "Live" ? 1 : 0;
            return bStatus - aStatus;
          })
          .map((user) => {
            return (
              <div
                key={user.id}
                className="user-card"
                onClick={() => (window.location.href = `/${user.Nick}`)}
              >
                <span className="user-name">{user.Nick}</span>
                <span className={`stream-status ${streamsStatus[user.Nick]}`}>
                  {streamsStatus[user.Nick] || "Checking..."}
                </span>
              </div>
            );
          })}
      </div>
    </div>
  );
}

export default App;