import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./App.css";
import bcrypt from "bcryptjs";
import { createClient } from "@supabase/supabase-js";

export const supabase = createClient(
  "https://dqeynvzwtvgfipvujqtk.supabase.co",
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRxZXludnp3dHZnZmlwdnVqcXRrIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NDExMDYxNzMsImV4cCI6MjA1NjY4MjE3M30.K3EPtek2a5C8qltgzOADpyEPPoQU_vRImHr6LjO9leA"
);

function Login() {
  const [login, setLogin] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!login || !password) return;

    try {
      const { data, error } = await supabase
        .from("Users")
        .select("*")
        .eq("Login", login);

      if (error || !data || data.length === 0) {
        alert("Неверный логин или пароль.");
        return;
      }
      for (const user of data) {
        const isMatch = await bcrypt.compare(password, user.Password);
        if (isMatch) {
          document.cookie = `role=${user.Role}; path=/; max-age=86400;`;
          document.cookie = `nick=${user.Nick}; path=/; max-age=86400;`;
          document.cookie = `userid=${user.id}; path=/; max-age=86400;`;
          navigate("/");
          navigate(0);
          return;
        }
      }
      alert("Неверный логин или пароль.");
    } catch (err) {
      console.error("Ошибка при входе:", err);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-box">
        <h2>Вход</h2>
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Логин:</label>
            <input
              value={login}
              onChange={(e) => setLogin(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <div className="input-group">
            <label>Пароль:</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <button type="submit">Вход</button>
        </form>
        <div className="switch-form">
          <p>Ещё нет аккаунта?</p>
          <button onClick={() => navigate("/signin")}>Регистрация</button>
        </div>
      </div>
    </div>
  );
}

export default Login;